#[test]
fn a_site_in_an_unresolved_calls_argument_is_counted_7609() -> Result<()> {
    for &(program, stderr, code) in ROWS {
        let got = run_jq_full(&["-n", program], None)?;
        assert_eq!(
            (got.0.as_str(), got.1.as_str(), got.2),
            ("", stderr, code),
            "{program:?}"
        );
    }
    Ok(())
}
